325	    /**
326	     * Move a claim to a status as {@link #move(String, String, long, ClaimStatus)}; a claim is voided with the
327	     * given reason, which while the sheet's list of void reasons is not empty must be on it, else the void is
328	     * refused (see {@link VoidReasons#require}).
329	     */
330	    @Transactional
331	    public long move(String sheetId, String user, long claimId, ClaimStatus next, String voidReason) {
332	        Claim claim = claim(sheetId, claimId);
333	        if (!claim.getStatus().canBecome(next)) {
334	            throw new ResponseStatusException(HttpStatus.CONFLICT,
335	                    "A " + claim.getStatus() + " claim cannot become " + next);
336	        }
337	        Permission permission = switch (next) {
338	            case OPEN -> Permission.OPEN;
339	            case SETTLED -> Permission.SETTLE;
340	            case VOID -> Permission.VOID;
341	            default -> null;
342	        };
343	        if (permission != null && !access.allows(sheetId, user, permission)) {
344	            throw new ResponseStatusException(HttpStatus.FORBIDDEN,
345	                    "Your role may not " + permission.action() + " a claim on this sheet");
346	        }
347	        String reasonGiven = next == ClaimStatus.VOID ? voidReasons.require(sheetId, voidReason) : null;
348	        String reversed = null;
349	        if (next == ClaimStatus.VOID && claim.getStatus() == ClaimStatus.SETTLED) {
350	            requireVoidableSettled(sheetId, user, claim);
351	            reversed = claim.getSettledDue() == null ? "n/a" : claim.getSettledDue().toPlainString();
352	        }
353	        if (next == ClaimStatus.SETTLED && Dues.deferred(claim, sheets.today(sheetId))) {
354	            throw new ResponseStatusException(HttpStatus.CONFLICT,
355	                    "The claim is deferred until " + claim.getDeferredUntil() + " and cannot be settled before then");
356	        }
357	        if (next == ClaimStatus.SETTLED && user.equals(claim.getOpenedBy())) {
358	            throw new ResponseStatusException(HttpStatus.FORBIDDEN,
359	                    "The user who opened a claim cannot settle it");
360	        }
361	        if (next == ClaimStatus.SETTLED && user.equals(claim.getEditedBy())) {
362	            throw new ResponseStatusException(HttpStatus.FORBIDDEN,
363	                    "The user who last edited a claim cannot settle it");
364	        }
365	        if (next == ClaimStatus.OPEN) {
366	            requireNote(sheetId, claim);
367	            requireUnderCap(sheetId, claim);
368	        }
369	        Rollup.Figures before = rollup.figures(sheetId);
370	        if (next == ClaimStatus.OPEN) {
371	            giveNumber(sheetId, claim);
372	            claim.setOpenedBy(user);
373	        }
374	        String number = claim.getShownNumber();
375	        Person owner = people.findByIdAndSheetId(claim.getPersonId(), sheetId).orElse(null);
376	        String due = null;
377	        if (next == ClaimStatus.SETTLED) {
378	            BigDecimal fixed = dueNow(sheetId, claim, owner);
379	            requireProof(sheetId, claim, owner, fixed);
380	            if (access.canSettle(sheetId, user, fixed)) {
381	                claim.setSettledDue(fixed);
382	                due = fixed == null ? "n/a" : fixed.toPlainString();
383	            } else {
384	                next = ClaimStatus.PENDING;
385	            }
386	        }
387	        claim.setStatus(next);
388	        if (next == ClaimStatus.VOID) {
389	            claim.setVoidReason(reasonGiven);
390	        }
391	        log(sheetId, user, claim, owner);
392	        claims.flush();
393	        String person = owner == null ? "" : owner.getName();
394	        String event = switch (next) {
395	            case OPEN -> "CLAIM_OPENED";
396	            case PENDING -> "CLAIM_PENDING";
397	            case SETTLED -> "CLAIM_SETTLED";
398	            case VOID -> "CLAIM_VOIDED";
399	            case DRAFT, DELETED -> throw new IllegalStateException();
400	        };
401	        events.publishEvent(new ClaimChanged(event, sheetId, user, person, claim.getAmount(), claim.getDate(), number,
402	                due, null, reversed, null, null, reasonGiven));
403	        if (next == ClaimStatus.SETTLED) {
404	            watches.notifyWatchers(sheetId, user, owner, number);
405	        }
406	        rollup.changed(sheetId, user, before);
407	        return claim.getPersonId();
408	    }
