426	     * Restore a DELETED claim to a DRAFT, only on the sheet's today it was deleted. A claim not DELETED, one
427	     * deleted on another day, or one due by a date inside a closed period is refused and nothing changes.
428	     * Returns the person it belongs to.
429	     */
430	    @Transactional
431	    public long restore(String sheetId, String user, long claimId) {
432	        Claim claim = claim(sheetId, claimId);
433	        if (claim.getStatus() != ClaimStatus.DELETED) {
434	            throw new ResponseStatusException(HttpStatus.CONFLICT,
435	                    "A " + claim.getStatus() + " claim cannot be restored; only a DELETED one can");
436	        }
437	        LocalDate deletedOn = claim.getLog().stream().filter(l -> l.getStatus() == ClaimStatus.DELETED)
438	                .map(ClaimLogLine::getOn).reduce((a, b) -> b).orElse(null);
439	        LocalDate today = sheets.today(sheetId);
440	        if (!today.equals(deletedOn)) {
441	            throw new ResponseStatusException(HttpStatus.CONFLICT,
442	                    "A claim can only be restored on the day it was deleted"
443	                            + (deletedOn == null ? "" : " (" + deletedOn + ")"));
444	        }
445	        return changeDeleted(sheetId, user, claim, ClaimStatus.DRAFT, "CLAIM_RESTORED");
446	    }
447	
448	    /** Move a claim between DRAFT and DELETED, logging and auditing it. Returns the person it belongs to. */
449	    private long changeDeleted(String sheetId, String user, Claim claim, ClaimStatus next, String event) {
450	        Rollup.Figures before = rollup.figures(sheetId);
451	        Person owner = people.findByIdAndSheetId(claim.getPersonId(), sheetId).orElse(null);
452	        claim.setStatus(next);
453	        claim.setLockedBy(null);
454	        log(sheetId, user, claim, owner);
455	        claims.flush();
456	        events.publishEvent(new ClaimChanged(event, sheetId, user, owner == null ? "" : owner.getName(),
457	                claim.getAmount(), claim.getDate(), null, null));
458	        rollup.changed(sheetId, user, before);
459	        return claim.getPersonId();
460	    }
461	
462	    /**
463	     * Defer an OPEN claim until a date after the sheet's today: until the sheet's today reaches it the claim
464	     * counts in no total, is not overdue, cannot be settled and no statement binds it (see
465	     * {@link Dues#deferred}). A claim not OPEN, a date not after today, or a claim due by a date inside a closed
466	     * period is refused and nothing changes. Returns the person it belongs to.
467	     */
468	    @Transactional
469	    public long defer(String sheetId, String user, long claimId, LocalDate until) {
470	        Claim claim = claim(sheetId, claimId);
471	        if (claim.getStatus() != ClaimStatus.OPEN) {
472	            throw new ResponseStatusException(HttpStatus.CONFLICT,
473	                    "A " + claim.getStatus() + " claim cannot be deferred; only an OPEN one can");
474	        }
475	        LocalDate today = sheets.today(sheetId);
476	        if (!until.isAfter(today)) {
477	            throw new ResponseStatusException(HttpStatus.CONFLICT,
478	                    "A claim can only be deferred to a date after the sheet's today (" + today + ")");
479	        }
480	        Rollup.Figures before = rollup.figures(sheetId);
481	        claim.setDeferredUntil(until);
482	        claims.flush();
483	        String person = people.findByIdAndSheetId(claim.getPersonId(), sheetId).map(Person::getName).orElse("");
484	        events.publishEvent(new ClaimDeferred(sheetId, user, person, claim.getAmount(), claim.getDate(),
485	                claim.getShownNumber(), until));
486	        rollup.changed(sheetId, user, before);
487	        return claim.getPersonId();
488	    }
489	
490	    /**
491	     * A steward re-dates an OPEN or PENDING claim. Its due-by stays as it was fixed and a figure a statement
492	     * bound it to stays bound; so does its period (the one containing its due-by) and its number. A claim
493	     * not OPEN or PENDING, one due by a date inside a closed period, a new date after its person's
494	     * retirement date, or a re-date by
495	     * anyone but a steward is refused and nothing changes. Returns the person it belongs to.
496	     */
497	    @Transactional
498	    public long redate(String sheetId, String user, long claimId, LocalDate date) {
499	        Claim claim = claim(sheetId, claimId);
500	        if (access.roleOf(sheetId, user) != Role.STEWARD) {
501	            throw new ResponseStatusException(HttpStatus.CONFLICT, "Only a steward can re-date a claim");
502	        }
503	        if (claim.getStatus() != ClaimStatus.OPEN && claim.getStatus() != ClaimStatus.PENDING) {
504	            throw new ResponseStatusException(HttpStatus.CONFLICT,
505	                    "A " + claim.getStatus() + " claim cannot be re-dated; only an OPEN or PENDING one can");
506	        }
507	        Person owner = people.findByIdAndSheetId(claim.getPersonId(), sheetId)
508	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such person"));
509	        requireNotRetired(owner, date);
510	        Rollup.Figures before = rollup.figures(sheetId);
511	        LocalDate old = claim.getDate();
512	        claim.setDate(date);
513	        claims.flush();
514	        events.publishEvent(new ClaimRedated(sheetId, user, owner.getName(), claim.getAmount(), claim.getDate(),
515	                claim.getShownNumber(), old, date));
516	        rollup.changed(sheetId, user, before);
517	        return claim.getPersonId();
518	    }
519	
520	    /**
521	     * Split an amount (more than 0.00 and less than the claim's amount) off an OPEN claim. The claim keeps
522	     * the rest and is released from any figure a statement bound it to; a new OPEN claim of the same person
523	     * takes the amount split off, with the same date and note, the next number, opened by the user and
524	     * due by its date plus the terms then of its person's grade on its date, naming the claim it was split
525	     * from, carrying its tags, and a late entry when that claim is. It is judged by the claim split alone: a claim not OPEN, a deferred one, one due by a date inside a closed period, an amount out of range, or a
526	     * split by a role the sheet's permission matrix does not allow to open a claim is refused and nothing
527	     * changes. Returns the person it belongs to.
528	     */
529	    @Transactional
530	    public long split(String sheetId, String user, long claimId, BigDecimal amount) {
531	        Claim claim = claim(sheetId, claimId);
532	        if (claim.getStatus() != ClaimStatus.OPEN) {
533	            throw new ResponseStatusException(HttpStatus.CONFLICT,
534	                    "A " + claim.getStatus() + " claim cannot be split; only an OPEN one can");
535	        }
536	        if (Dues.deferred(claim, sheets.today(sheetId))) {
537	            throw new ResponseStatusException(HttpStatus.CONFLICT,
538	                    "The claim is deferred until " + claim.getDeferredUntil() + " and cannot be split");
539	        }
540	        if (!access.allows(sheetId, user, Permission.OPEN)) {
541	            throw new ResponseStatusException(HttpStatus.FORBIDDEN, "Your role may not open a claim on this sheet");
542	        }
543	        if (amount.signum() <= 0 || amount.compareTo(claim.getAmount()) >= 0) {
544	            throw new ResponseStatusException(HttpStatus.CONFLICT,
545	                    "The amount split off must be more than 0.00 and less than " + claim.getAmount().toPlainString());
546	        }
547	        Person owner = people.findByIdAndSheetId(claim.getPersonId(), sheetId)
548	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such person"));
549	        Rollup.Figures before = rollup.figures(sheetId);
550	        claim.setAmount(claim.getAmount().subtract(amount));
551	        claim.unbind();
552	        Claim part = new Claim(sheetId, owner.getId(), amount, claim.getDate(), claim.getNote(), null);
553	        sheets.load(sheetId, user);
554	        int terms = sheets.settings(sheetId).termsFor(owner.getTerms(), owner.gradeOn(claim.getDate()), claim.getDate());
555	        part.setDueBy(holidays.dueBy(sheetId, claim.getDate(), terms));
556	        part.setTerms(terms);
557	        part.setSplitFrom(claim.getShownNumber());
558	        part.setTags(claim.getTags());
559	        part.setLateEntry(claim.isLateEntry());
560	        giveNumber(sheetId, part);
561	        part.setOpenedBy(user);
562	        part.setStatus(ClaimStatus.OPEN);
563	        log(sheetId, user, part, owner);
564	        claims.saveAndFlush(part);
565	        events.publishEvent(new ClaimSplit(sheetId, user, owner.getName(), claim.getAmount(), claim.getDate(),
566	                claim.getShownNumber(), part.getShownNumber()));
567	        events.publishEvent(new ClaimChanged("CLAIM_OPENED", sheetId, user, owner.getName(), part.getAmount(),
568	                part.getDate(), part.getShownNumber(), null));
569	        rollup.changed(sheetId, user, before);
570	        return owner.getId();
571	    }
572	
573	    /**
574	     * Add a line to a DRAFT claim: its amount becomes its lines' quantities times their unit amounts added up.
575	     * Adding a line counts as editing the claim: a claim not a DRAFT, one due by a date inside a closed period
576	     * or one another user's editor holds is refused and nothing changes. Returns the person it belongs to.
577	     */
578	    @Transactional
579	    public long addLine(String sheetId, String user, long claimId, String label, int qty, BigDecimal unit) {
580	        if (label == null || label.isBlank()) {
581	            throw new ResponseStatusException(HttpStatus.BAD_REQUEST, "A line needs a label");
582	        }
583	        if (qty < 1) {
584	            throw new ResponseStatusException(HttpStatus.BAD_REQUEST, "A line's quantity must be at least 1");
585	        }
586	        if (unit.scale() > 2) {
587	            throw new ResponseStatusException(HttpStatus.BAD_REQUEST, "A line's unit amount has two decimals");
588	        }
589	        Claim claim = claim(sheetId, claimId);
590	        if (claim.getStatus() != ClaimStatus.DRAFT) {
591	            throw new ResponseStatusException(HttpStatus.CONFLICT,
592	                    "A " + claim.getStatus() + " claim cannot be edited; void it and add a new one");
593	        }
594	        requireNotLockedByOther(claim, user);
595	        Rollup.Figures before = rollup.figures(sheetId);
596	        BigDecimal at = unit.setScale(2);
597	        claim.addLine(label.strip(), qty, at);
598	        claim.setEditedBy(user);
599	        claims.flush();
600	        String person = people.findByIdAndSheetId(claim.getPersonId(), sheetId).map(Person::getName).orElse("");
601	        events.publishEvent(new ClaimLineAdded(sheetId, user, person, claim.getAmount(), claim.getDate(),
602	                claim.getShownNumber(), label.strip(), qty, at));
603	        rollup.changed(sheetId, user, before);
604	        return claim.getPersonId();
605	    }
606	
607	    /**
608	     * Add a proof to a claim, raising its proofs count by one. A SETTLED or VOID claim, or a claim dated
609	     * inside a closed period, is refused and nothing changes. Returns the person it belongs to.
610	     */
611	    @Transactional
612	    public long addProof(String sheetId, String user, long claimId) {
613	        Claim claim = claim(sheetId, claimId);
614	        if (claim.getStatus() == ClaimStatus.SETTLED || claim.getStatus() == ClaimStatus.VOID) {
615	            throw new ResponseStatusException(HttpStatus.CONFLICT,
616	                    "A " + claim.getStatus() + " claim cannot take a proof");
617	        }
618	        claim.addProof();
619	        claims.flush();
620	        String person = people.findByIdAndSheetId(claim.getPersonId(), sheetId).map(Person::getName).orElse("");
621	        events.publishEvent(new ClaimProofAdded(sheetId, user, person, claim.getAmount(), claim.getDate(),
622	                claim.getShownNumber(), claim.getProofs()));
623	        return claim.getPersonId();
624	    }
625	
626	    /**
627	     * Comment a claim, in any status: the comment is kept with the user and the sheet's today. A blank
628	     * comment is refused and nothing changes. Returns the person it belongs to.
629	     */
630	    @Transactional
631	    public long comment(String sheetId, String user, long claimId, String text) {
632	        if (text == null || text.isBlank()) {
633	            throw new ResponseStatusException(HttpStatus.BAD_REQUEST, "A comment cannot be empty");
634	        }
635	        Claim claim = claims.findByIdAndSheetId(claimId, sheetId)
636	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such claim"));
637	        String comment = text.trim();
638	        claim.comment(user, sheets.today(sheetId), comment);
639	        claims.flush();
640	        String person = people.findByIdAndSheetId(claim.getPersonId(), sheetId).map(Person::getName).orElse("");
641	        events.publishEvent(new ClaimCommented(sheetId, user, person, claim.getAmount(), claim.getDate(),
642	                claim.getShownNumber(), comment));
643	        return claim.getPersonId();
644	    }
645	
646	    /**
647	     * Remind an OPEN or PENDING claim: it takes the sheet's today as its reminded date. A claim can be
648	     * reminded once per sheet's today; a claim in any other status, or one already reminded on the sheet's
649	     * today, is refused and nothing changes. A reminder changes no figure, so a claim due by a date inside a
650	     * closed period can still be reminded. Returns the person it belongs to.
651	     */
652	    @Transactional
653	    public long remind(String sheetId, String user, long claimId) {
654	        Claim claim = claims.findByIdAndSheetId(claimId, sheetId)
655	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such claim"));
656	        if (!claim.getStatus().unpaid()) {
657	            throw new ResponseStatusException(HttpStatus.CONFLICT,
658	                    "A " + claim.getStatus() + " claim cannot be reminded; only an OPEN or PENDING one can");
659	        }
660	        LocalDate today = sheets.today(sheetId);
661	        if (today.equals(claim.getRemindedOn())) {
662	            throw new ResponseStatusException(HttpStatus.CONFLICT, "The claim was already reminded today (" + today + ")");
663	        }
664	        claim.setRemindedOn(today);
665	        claims.flush();
666	        String person = people.findByIdAndSheetId(claim.getPersonId(), sheetId).map(Person::getName).orElse("");
667	        events.publishEvent(new ClaimReminded(sheetId, user, person, claim.getAmount(), claim.getDate(),
668	                claim.getShownNumber()));
669	        return claim.getPersonId();
670	    }
671	
672	    /**
673	     * Refuse opening a claim with an empty note whose due (null: n/a) is above the sheet's note threshold in
674	     * force on the claim's date.
675	     */
676	    private void requireNote(String sheetId, Claim claim) {
677	        if (claim.getNote() != null && !claim.getNote().isBlank()) {
678	            return;
679	        }
680	        BigDecimal threshold = sheets.settings(sheetId).noteThreshold(claim.getDate());
681	        if (threshold == null) {
682	            return;
683	        }
684	        Person owner = people.findByIdAndSheetId(claim.getPersonId(), sheetId).orElse(null);
685	        BigDecimal due = dueNow(sheetId, claim, owner);
686	        if (due != null && due.compareTo(threshold) > 0) {
687	            throw new ResponseStatusException(HttpStatus.CONFLICT,
688	                    "A claim with a due above " + threshold.toPlainString() + " needs a note to be opened");
689	        }
690	    }
691	
692	    /**
693	     * Refuse settling or approving a claim with no proof whose due (null: n/a) is above the proof threshold
694	     * in force on the claim's date: its owner's grade's then when one is set, else the sheet's.
695	     */
696	    private void requireProof(String sheetId, Claim claim, Person owner, BigDecimal due) {
697	        if (due == null || claim.getProofs() > 0) {
698	            return;
699	        }
700	        String grade = owner == null ? null : owner.gradeOn(claim.getDate());
701	        BigDecimal threshold = sheets.settings(sheetId).proofThresholdFor(grade, claim.getDate());
702	        if (threshold != null && due.compareTo(threshold) > 0) {
703	            throw new ResponseStatusException(HttpStatus.CONFLICT,
704	                    "A claim with a due above " + threshold.toPlainString() + " needs a proof to be settled");
705	        }
706	    }
